import { copyFileSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import path from "node:path";
import { build, version as viteVersion } from "vite";
import {
  BUILD_SCRIPT,
  BUNDLE_ENTRY,
  BUNDLE_PATH,
  MANIFEST_PATH,
  ROOT,
  WINDOW_BUNDLE_ENTRY,
  WINDOW_BUNDLE_PATH,
  relativePath,
  sha256Text,
  sourcesFingerprint,
} from "./bundle-files.mjs";

const TMP_ROOT = path.join(ROOT, "tmp", "cheat-bundles");

// NW.js exposes Node's fs/path and nw.gui through the global require. They must
// stay runtime calls: Vite's browser defaults would otherwise replace Node
// builtins with an empty module and silently break settings persistence.
const NODE_EXTERNALS = ["fs", "path", "nw.gui"];

const BUNDLES = [
  {
    label: "overlay",
    entry: BUNDLE_ENTRY,
    outputName: "setup.bundle.js",
    outputPath: BUNDLE_PATH,
    outDir: path.join(TMP_ROOT, "overlay"),
    // The overlay is a plain static graph: one request for one file.
    singleFile: false,
    // Vue and Vuetify are vendored scripts loaded by the host page.
    externals: [...NODE_EXTERNALS, "../libs/vue.js", "../libs/vuetify.js"],
    expectVendorImports: true,
    banner:
      "/*! RPG Maker Cheat UI overlay - generated by tools/vendor/build-bundles.mjs. Edit the source modules, not this file. */",
  },
  {
    label: "pop-out",
    entry: WINDOW_BUNDLE_ENTRY,
    outputName: "window-init.bundle.js",
    outputPath: WINDOW_BUNDLE_PATH,
    outDir: path.join(TMP_ROOT, "popout"),
    // window-init.js imports the UI *after* it bridged the game globals. The
    // bundle must keep that ordering, so the imports are inlined into the same
    // file instead of becoming separate chunks; no module touches RPG Maker
    // globals at evaluation time, so eager evaluation is safe.
    singleFile: true,
    externals: [...NODE_EXTERNALS],
    expectVendorImports: false,
    banner:
      "/*! RPG Maker Cheat UI separate window - generated by tools/vendor/build-bundles.mjs. Edit the source modules, not this file. */",
  },
];

const escapeRegExp = (value) => value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const externalImport = (fileName) =>
  new RegExp(`import\\s+["']\\.\\./libs/${escapeRegExp(fileName)}["']`);

function verifyBundle(config, text) {
  const problems = [];
  if (!text.includes(config.banner)) problems.push("missing build banner");

  if (config.expectVendorImports) {
    if (!externalImport("vue.js").test(text))
      problems.push("Vue external import was rewritten");
    if (!externalImport("vuetify.js").test(text))
      problems.push("Vuetify external import was rewritten");
  } else if (text.includes("../libs/")) {
    problems.push("pop-out must use the host page's Vue/Vuetify globals");
  }

  if (text.includes("__vite-browser-external"))
    problems.push("Node builtins were replaced by Vite browser shims");
  if (!text.includes("typeof require"))
    problems.push("runtime require() interop was removed");
  for (const moduleName of NODE_EXTERNALS) {
    const runtimeRequire = new RegExp(
      `[A-Za-z_$][\\w$]*\\(["']${escapeRegExp(moduleName)}["']\\)`,
    );
    if (!runtimeRequire.test(text))
      problems.push(
        `runtime require("${moduleName}") call was not preserved`,
      );
  }
  if (text.includes("import.meta")) problems.push("bundle relies on import.meta");
  if (/(cdn\.jsdelivr\.net|fonts\.googleapis\.com|unpkg\.com)/.test(text))
    problems.push("bundle references a CDN asset");
  if (config.singleFile) {
    // A leftover import() would point at a source module that bundle-only
    // installs do not ship.
    if (/\bimport\s*\(\s*["']\.{1,2}\//.test(text))
      problems.push("dynamic import survived the single-file bundle");
  }
  if (text.length < 200_000 || text.length > 1_200_000)
    problems.push(`unexpected bundle size ${text.length} bytes`);

  if (problems.length) {
    throw new Error(
      `${config.label} bundle verification failed:\n- ` +
        problems.join("\n- "),
    );
  }
}

async function buildBundle(config) {
  rmSync(config.outDir, { recursive: true, force: true });

  const result = await build({
    configFile: false,
    root: ROOT,
    logLevel: "warn",
    build: {
      outDir: config.outDir,
      emptyOutDir: true,
      target: "chrome61",
      minify: true,
      sourcemap: false,
      lib: {
        entry: config.entry,
        formats: ["es"],
        fileName: () => config.outputName,
      },
      rollupOptions: {
        external: (id) => config.externals.includes(id),
        output: {
          banner: config.banner,
          codeSplitting: !config.singleFile,
        },
      },
    },
  });

  const output = Array.isArray(result)
    ? result.flatMap((entry) => entry.output)
    : result.output;
  const chunks = output.filter((entry) => entry.type === "chunk");
  const assets = output.filter((entry) => entry.type === "asset");
  if (chunks.length !== 1 || assets.length !== 0) {
    throw new Error(
      `${config.label} bundle expected one JavaScript chunk and no assets, got ` +
        JSON.stringify(output.map((entry) => entry.fileName)),
    );
  }

  const builtPath = path.join(config.outDir, chunks[0].fileName);
  const text = readFileSync(builtPath, "utf8");
  verifyBundle(config, text);
  return { config, builtPath, text };
}

const built = [];
for (const config of BUNDLES) {
  built.push(await buildBundle(config));
}

const manifestBundles = {};
for (const { config, builtPath, text } of built) {
  copyFileSync(builtPath, config.outputPath);
  manifestBundles[relativePath(config.outputPath)] = sha256Text(text);
}

const manifest = {
  generatedBy: relativePath(BUILD_SCRIPT),
  vite: viteVersion,
  sourcesHash: sourcesFingerprint(),
  bundles: manifestBundles,
};
writeFileSync(MANIFEST_PATH, JSON.stringify(manifest, null, 2) + "\n", "utf8");

for (const { config, text } of built) {
  console.log(
    `Built ${relativePath(config.outputPath)}: ${(text.length / 1024).toFixed(1)} KB, Vite ${viteVersion}`,
  );
}
